function threeSum(nums: number[]): number[][] {
  // Сортировка позволяет использовать два указателя и легко пропускать дубликаты
  nums.sort((a, b) => a - b);
  const result: number[][] = [];

  for (let i = 0; i < nums.length - 2; i++) {
    // Если наименьшее число > 0, сумма трёх уже не может быть нулём
    if (nums[i] > 0) break;

    // Пропускаем одинаковые первые числа, чтобы не получить повторяющиеся тройки
    if (i > 0 && nums[i] === nums[i - 1]) continue;

    // Ищем пару с суммой -nums[i] справа от i (как в Two Sum II)
    let left = i + 1;
    let right = nums.length - 1;

    while (left < right) {
      const sum = nums[i] + nums[left] + nums[right];

      if (sum < 0) {
        left++;
      } else if (sum > 0) {
        right--;
      } else {
        result.push([nums[i], nums[left], nums[right]]);
        left++;
        right--;

        // Пропускаем дубликаты второго числа (третье подстроится само)
        while (left < right && nums[left] === nums[left - 1]) left++;
      }
    }
  }

  return result;
}

// Время: O(n²) — сортировка O(n log n) + для каждого i проход двумя указателями
// Память: O(1) дополнительно (не считая ответа и сортировки)
